// Beginner teaching sequence. Canonical page numbers stay stable; classroom
// sessions below divide the material into smaller, connected 45-minute lessons.
const diagram = name => `/assets/course-v3/section-3/${name}.svg`;
const imagegen = name => `/assets/diagrams/course-v3-imagegen/${name}.png`;
const startTraceRows = Array.from({ length: 8 }, (_, n) => {
  const a = (n >> 2) & 1;
  const b = (n >> 1) & 1;
  const c = n & 1;
  return [a, b, c, a | b, 1 - c, (a | b) & (1 - c)];
});
const startSourceTable = { headers: ['A', 'B', 'C', 'Q'], rows: startTraceRows.map(([a, b, c, , , q]) => [a, b, c, q]) };
const startTraceTable = { headers: ['A', 'B', 'C', 'X = A OR B', 'Y = NOT C', 'Q = X AND Y'], rows: startTraceRows };

